        hs = f"{h:02d}"
        if (s[0] == '?' or s[0] == hs[0]) and (s[1] == '?' or s[1] == hs[1]):
            for m in range(59, -1, -1):
                ms = f"{m:02d}"
                if (s[3] == '?' or s[3] == ms[0]) and (s[4] == '?' or s[4] == ms[1]):
