    is_empty = [[False]*W for _ in range(H)]
    is_free = [[False]*W for _ in range(H)]
    for i in range(H):
        for j in range(W):
            if S[i][j] == '.':
                is_empty[i][j] = True
                adj_magnet = False
                for di,dj in dirs:
                    ni,nj = i+di,j+dj
                    if 0<=ni<H and 0<=nj<W and S[ni][nj]=='#':
                        adj_magnet = True
                        break
                if not adj_magnet:
                    is_free[i][j] = True

    visited = [[False]*W for _ in range(H)]
    max_deg = 1

    for i in range(H):
        for j in range(W):
            if is_free[i][j] and not visited[i][j]:
                comp = []
                q = deque()
                q.append((i,j))
                visited[i][j] = True
                while q:
                    x,y = q.popleft()
                    comp.append((x,y))
                    for dx,dy in dirs:
                        nx,ny = x+dx,y+dy
                        if 0<=nx<H and 0<=ny<W and is_free[nx][ny] and not visited[nx][ny]:
                            visited[nx][ny] = True
                            q.append((nx,ny))
                blocked_set = set()
                for x,y in comp:
                    for dx,dy in dirs:
                        nx,ny = x+dx,y+dy
                        if 0<=nx<H and 0<=ny<W and not is_empty[nx][ny]:
                            blocked_set.add((nx,ny))
                        elif 0<=nx<H and 0<=ny<W and is_empty[nx][ny] and not is_free[nx][ny]:
                            blocked_set.add((nx,ny))
                deg = len(comp) + len(blocked_set)
                if deg > max_deg:
                    max_deg = deg

    print(max_deg)

