        cells = []
        for i in range(4):
            for j in range(4):
                if shape[i][j] == '#':
                    cells.append((i, j))
        return cells

    def rotate(cells, k):
        res = cells[:]
        for _ in range(k):
            res = [(y, 3 - x) for x, y in res]
        return res

    def get_placements(cells):
        placements = set()
        for k in range(4):
            rot = rotate(cells, k)
            if not rot:
                continue
            minr = min(r for r, c in rot)
            maxr = max(r for r, c in rot)
            minc = min(c for r, c in rot)
            maxc = max(c for r, c in rot)
            for sr in range(-minr, 4 - maxr):
                for sc in range(-minc, 4 - maxc):
                    placed = frozenset((r + sr, c + sc) for r, c in rot)
                    placements.add(placed)
        return list(placements)

    all_placements = []
    sizes = []
    for poly in polys:
        cells = get_cells(poly)
        sizes.append(len(cells))
        if sum(sizes) > 16:
            print("No")
            return
        placements = get_placements(cells)
        all_placements.append(placements)

    if sum(sizes) != 16:
        print("No")
        return

    for combo in product(*all_placements):
        covered = set()
        overlap = False
        for placed in combo:
            for pos in placed:
                if pos in covered:
                    overlap = True
                    break
                covered.add(pos)
            if overlap:
                break
        if not overlap and len(covered) == 16:
            print("Yes")
            return
    print("No")

