import math
MOD = 10**9 + 7
def numberOfSequence(n, sick):
    m = n - len(sick)
    if m == 0:
        return 1
    gaps = []
    gaps.append(sick[0])
    for i in range(1, len(sick)):
        g = sick[i] - sick[i-1] - 1
        if g > 0:
            gaps.append(g)
    gaps.append(n - 1 - sick[-1])
    res = math.factorial(m)
    for g in gaps:
        res = (res * pow(math.factorial(g), MOD-2, MOD)) % MOD
    for i in range(1, len(sick)):
        g = sick[i] - sick[i-1] - 1
        if g > 0:
            res = (res * pow(2, g-1, MOD)) % MOD
    return res
