def beautifulNumbers(low, high, k):
    def count_up_to(n, k):
        if n < 0:
            return 0
        s = str(n)
        L = len(s)
        from functools import lru_cache
        @lru_cache(None)
        def dp(pos, tight, started, mod, diff):
            if pos == L:
                return 1 if started and mod == 0 and diff == 0 else 0
            res = 0
            up = int(s[pos]) if tight else 9
            for d in range(up + 1):
                new_tight = tight and (d == up)
                if not started and d == 0:
                    new_started = False
                    new_mod = 0
                    new_diff = 0
                else:
                    new_started = True
                    new_mod = (mod * 10 + d) % k
                    parity = 0 if d % 2 == 0 else 1
                    new_diff = diff + (1 if parity == 0 else -1)
                res += dp(pos + 1, new_tight, new_started, new_mod if new_started else 0, new_diff if new_started else 0)
            return res
        return dp(0, True, False, 0, 0)
    return count_up_to(high, k) - count_up_to(low - 1, k)
