def minMaxDistance(points):
    n = len(points)
    s = [x + y for x, y in points]
    d = [x - y for x, y in points]
    min_s, max_s = min(s), max(s)
    min_d, max_d = min(d), max(d)
    sec_min_s = sec_max_s = sec_min_d = sec_max_d = None
    for val in s:
        if val > min_s and (sec_min_s is None or val < sec_min_s):
            sec_min_s = val
        if val < max_s and (sec_max_s is None or val > sec_max_s):
            sec_max_s = val
    for val in d:
        if val > min_d and (sec_min_d is None or val < sec_min_d):
            sec_min_d = val
        if val < max_d and (sec_max_d is None or val > sec_max_d):
            sec_max_d = val
    if sec_min_s is None: sec_min_s = min_s
    if sec_max_s is None: sec_max_s = max_s
    if sec_min_d is None: sec_min_d = min_d
    if sec_max_d is None: sec_max_d = max_d
    candidates = set()
    for i in range(n):
        if s[i] == min_s or s[i] == max_s or d[i] == min_d or d[i] == max_d:
            candidates.add(i)
    def get_new_range(val, minv, maxv, sec_min, sec_max, cnt_max, cnt_min):
        new_min, new_max = minv, maxv
        if val == maxv:
            if cnt_max >= 2:
                new_max = maxv
            else:
                new_max = sec_max
        if val == minv:
            if cnt_min >= 2:
                new_min = minv
            else:
                new_min = sec_min
        return new_max - new_min
    cnt_max_s = s.count(max_s)
    cnt_min_s = s.count(min_s)
    cnt_max_d = d.count(max_d)
    cnt_min_d = d.count(min_d)
    ans = float('inf')
    orig_rs = max_s - min_s
    orig_rd = max_d - min_d
    for i in candidates:
        new_rs = get_new_range(s[i], min_s, max_s, sec_min_s, sec_max_s, cnt_max_s, cnt_min_s)
        new_rd = get_new_range(d[i], min_d, max_d, sec_min_d, sec_max_d, cnt_max_d, cnt_min_d)
        ans = min(ans, max(new_rs, new_rd))
    return ans
