def minimumOperations(word: str) -> int:
    n = len(word)
    if n == 0:
        return 0
    INF = float('inf')
    dp = [[INF] * 26 for _ in range(n)]
    for c in range(26):
        dp[0][c] = 0 if c == ord(word[0]) - ord('a') else 1
    for i in range(1, n):
        orig = ord(word[i]) - ord('a')
        for prev in range(26):
            if dp[i-1][prev] == INF:
                continue
            for curr in range(26):
                if abs(prev - curr) <= 1:
                    continue
                cost = 0 if curr == orig else 1
                dp[i][curr] = min(dp[i][curr], dp[i-1][prev] + cost)
    return min(dp[n-1])
