def minChanges(s: str, k: int) -> int:
    n = len(s)
    INF = 10**9
    cost = [[INF] * n for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            length = j - i + 1
            if length < 2:
                continue
            divisors = [d for d in range(1, length) if length % d == 0]
            min_c = INF
            for d in divisors:
                c = 0
                m = length // d
                for r in range(d):
                    seq = [s[i + r + t * d] for t in range(m)]
                    for p in range(m // 2):
                        if seq[p] != seq[m - 1 - p]:
                            c += 1
                if c < min_c:
                    min_c = c
            cost[i][j] = min_c
    dp = [[INF] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 0
    for parts in range(1, k + 1):
        for end in range(2 * parts, n + 1):
            for start in range(2 * (parts - 1), end - 1):
                if dp[start][parts - 1] != INF and cost[start][end - 1] != INF:
                    dp[end][parts] = min(dp[end][parts], dp[start][parts - 1] + cost[start][end - 1])
    return dp[n][k]
