from typing import List
from collections import Counter

def countSubMultisets(nums: List[int], l: int, r: int) -> int:
    MOD = 10**9 + 7
    freq = Counter(nums)
    zeros = freq[0]
    S = sum(nums)
    dp = [0] * (S + 1)
    dp[0] = 1
    for num in freq:
        if num == 0:
            continue
        f = freq[num]
        # Use cumulative sum for efficiency
        for s in range(num, S + 1):
            if s - num * (f + 1) >= 0:
                dp[s] = (dp[s] + dp[s - num] - dp[s - num * (f + 1)]) % MOD
            else:
                dp[s] = (dp[s] + dp[s - num]) % MOD
        # Handle negative modulo
        for s in range(S + 1):
            if dp[s] < 0:
                dp[s] += MOD
    total = 0
    mult = zeros + 1
    for s in range(l, min(r, S) + 1):
        total = (total + dp[s] * mult) % MOD
    if l == 0:
        total = (total + mult) % MOD
    return total
