class TrieNode:
    def __init__(self):
        self.children = {}
        self.best = -1

def answer(wordsContainer, wordsQuery):
    n = len(wordsContainer)
    lengths = [len(w) for w in wordsContainer]
    root = TrieNode()
    def should_update(new_idx, old_idx):
        if old_idx == -1:
            return True
        ln = lengths[new_idx]
        lo = lengths[old_idx]
        if ln < lo:
            return True
        if ln == lo and new_idx < old_idx:
            return True
        return False
    for i in range(n):
        node = root
        if should_update(i, node.best):
            node.best = i
        for c in reversed(wordsContainer[i]):
            if c not in node.children:
                node.children[c] = TrieNode()
            node = node.children[c]
            if should_update(i, node.best):
                node.best = i
    ans = []
    for q in wordsQuery:
        node = root
        res = root.best
        for c in reversed(q):
            if c not in node.children:
                break
            node = node.children[c]
            res = node.best
        ans.append(res)
    return ans
