def minimize_value(s):
    n = len(s)
    count = [0] * 26
    qpos = []
    for i, ch in enumerate(s):
        if ch == '?':
            qpos.append(i)
        else:
            count[ord(ch) - ord('a')] += 1
    q = len(qpos)
    f = count[:]
    for _ in range(q):
        min_idx = min(range(26), key=lambda x: f[x])
        f[min_idx] += 1
    rem = [f[i] - count[i] for i in range(26)]
    res = list(s)
    for pos in qpos:
        for c in range(26):
            if rem[c] > 0:
                res[pos] = chr(ord('a') + c)
                rem[c] -= 1
                break
    return ''.join(res)
