def countPairs(coordinates, k):
    from collections import defaultdict

    count = 0
    freq = defaultdict(int)

    for x, y in coordinates:
        # Check for matching pairs in the frequency dictionary
        for dx in range(max(0, x - k), min(10**6, x + k + 1)):
            for dy in range(max(0, y - k), min(10**6, y + k + 1)):
                if (dx ^ x) + (dy ^ y) == k:
