            for o in range(min(len(x), len(y)), 0, -1):
                if x.endswith(y[:o]):
                    s = x + y[o:]
                    merged = True
                    break
            if not merged:
                s = x + y
        if len(s) < min_len:
            min_len = len(s)
            ans = s
        elif len(s) == min_len and (ans is None or s < ans):
            ans = s
