def maximumLength(x: int, y: int, z: int) -> int:
    @functools.lru_cache(None)
    def dfs(a, b, c, last, cnt):
        ans = 0
        if last == -1:
            if a:
                ans = max(ans, 2 + dfs(a-1, b, c, 0, 2))
            if b:
                ans = max(ans, 2 + dfs(a, b-1, c, 1, 2))
            if c:
                ans = max(ans, 2 + dfs(a, b, c-1, 1, 1))
            return ans
        if a > 0:
            if last == 0 and cnt + 2 <= 2:
                ans = max(ans, 2 + dfs(a-1, b, c, 0, cnt + 2))
            if last == 1:
                ans = max(ans, 2 + dfs(a-1, b, c, 0, 2))
        if b > 0:
            if last == 1 and cnt + 2 <= 2:
                ans = max(ans, 2 + dfs(a, b-1, c, 1, cnt + 2))
            if last == 0:
                ans = max(ans, 2 + dfs(a, b-1, c, 1, 2))
        if c > 0:
            if last == 0 and cnt + 1 <= 2:
                ans = max(ans, 2 + dfs(a, b, c-1, 1, 1))
            if last == 1:
                ans = max(ans, 2 + dfs(a, b, c-1, 1, 1))
        return ans
    return dfs(x, y, z, -1, 0)
