def maximumXorProduct(a: int, b: int, n: int) -> int:
    if n == 0:
        return (a * b) % MOD
    mask = (1 << n) - 1
    A = a & ~mask
    B = b & ~mask
    D = a ^ b
    S = 0
    for k in range(n):
        if (D & (1 << k)) == 0:
            S += (1 << k)
    A += S
    B += S
    T = D & mask
    y, z = A, B
    for k in range(n - 1, -1, -1):
        if (D & (1 << k)) != 0:
            if y <= z:
                y += (1 << k)
            else:
                z += (1 << k)
    return (y * z) % MOD
