def maxSum(nums):
    n = len(nums)
    def get_key(x):
        res = 1
        for i in range(2, int(math.sqrt(x)) + 1):
            cnt = 0
            while x % i == 0:
                cnt += 1
                x //= i
            if cnt % 2:
                res *= i
        if x > 1:
            res *= x
        return res
    groups = defaultdict(int)
