def get_square_free(x, spf):
    if x == 0:
        return 0
    res = 1
    while x > 1:
        p = spf[x]
        cnt = 0
        while x % p == 0:
            x //= p
            cnt += 1
        if cnt % 2 == 1:
            res *= p
    return res

