def countCompleteSubstrings(word: str, k: int) -> int:
    def count_in_segment(s: str) -> int:
        m = len(s)
        res = 0
        max_d = min(26, m // k)
        for d in range(1, max_d + 1):
            L = d * k
            if L > m:
                break
            freq = [0] * 26
            bad = 0
            for i in range(m):
                c = ord(s[i]) - ord('a')
                prev = freq[c]
                freq[c] += 1
                curr = freq[c]
                if prev == 0 or prev == k:
                    if curr != 0 and curr != k:
                        bad += 1
                else:
                    if curr == 0 or curr == k:
                        bad -= 1
                if i >= L - 1:
                    if bad == 0:
                        res += 1
                    out_c = ord(s[i - L + 1]) - ord('a')
                    prev_out = freq[out_c]
                    freq[out_c] -= 1
                    curr_out = freq[out_c]
                    if prev_out == 0 or prev_out == k:
                        if curr_out != 0 and curr_out != k:
                            bad += 1
                    else:
                        if curr_out == 0 or curr_out == k:
                            bad -= 1
        return res

    n = len(word)
    total = 0
    i = 0
    while i < n:
        j = i
        while j + 1 < n and abs(ord(word[j]) - ord(word[j + 1])) <= 2:
            j += 1
        total += count_in_segment(word[i:j + 1])
        i = j + 1
    return total
