    total_area = H * W

    def can_tile(selected):
        # selected is list of (h, w) for chosen orientations
        k = len(selected)
        if k == 0:
            return False
        grid = [[False for _ in range(W)] for _ in range(H)]

        def find_empty():
            for r in range(H):
                for c in range(W):
                    if not grid[r][c]:
                        return r, c
            return None

        def can_place(r, c, h, w):
            if r + h > H or c + w > W:
                return False
            for i in range(h):
                for j in range(w):
                    if grid[r + i][c + j]:
                        return False
            return True

        def do_place(r, c, h, w, val):
            for i in range(h):
                for j in range(w):
                    grid[r + i][c + j] = val

        def bt(used_mask, placed):
            if placed == k:
                return find_empty() is None
            pos = find_empty()
            if pos is None:
                return False
            r, c = pos
            for t in range(k):
                if (used_mask & (1 << t)) == 0:
                    h, w = selected[t]
                    for orient in [(h, w), (w, h)]:
                        hh, ww = orient
                        # try all possible top-left that cover (r,c)
                        for dr in range(hh):
                            for dc in range(ww):
                                tr = r - dr
                                tc = c - dc
                                if tr < 0 or tc < 0 or tr + hh > H or tc + ww > W:
                                    continue
                                if can_place(tr, tc, hh, ww):
                                    do_place(tr, tc, hh, ww, True)
                                    if bt(used_mask | (1 << t), placed + 1):
                                        return True
                                    do_place(tr, tc, hh, ww, False)
            return False

        return bt(0, 0)

    # enumerate subsets
    for mask in range(1, 1 << N):
        area = 0
        selected = []
        for i in range(N):
            if mask & (1 << i):
                a, b = tiles[i]
                area += a * b
                selected.append((a, b))
        if area == total_area:
