def shortest_subarray(nums, target):
    n = len(nums)
    S = sum(nums)
    if S == 0:
        return -1
    q = target // S
    r = target % S
    extended = nums + nums
    pre = [0]
    for x in extended:
        pre.append(pre[-1] + x)
    def min_len_for_sum(X):
        if X == 0:
            return 0
        seen = {}
        minl = math.inf
        for j in range(len(pre)):
            if pre[j] - X in seen:
                minl = min(minl, j - seen[pre[j] - X])
            if pre[j] not in seen:
                seen[pre[j]] = j
        return minl if minl != math.inf else -1
    candidates = []
    len1 = min_len_for_sum(r)
    if len1 != -1:
        candidates.append(len1 + q * n)
    if q >= 1:
        len2 = min_len_for_sum(r + S)
        if len2 != -1:
            candidates.append(len2 + (q - 1) * n)
    if r == 0 and q >= 1:
        candidates.append(q * n)
    if not candidates:
        return -1
    res = min(candidates)
    return res if res > 0 else -1
