from typing import List

def canSplitArray(nums: List[int], m: int) -> bool:
    n = len(nums)
    if n == 1:
        return True
    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i + 1] = prefix[i] + nums[i]
    memo = {}
    def can(i: int, j: int) -> bool:
        if i == j:
            return True
        key = (i, j)
        if key in memo:
            return memo[key]
        total = prefix[j + 1] - prefix[i]
        res = False
        for k in range(i, j):
            left_len = k - i + 1
            right_len = j - k
            left_sum = prefix[k + 1] - prefix[i]
            right_sum = prefix[j + 1] - prefix[k + 1]
            left_ok = (left_len == 1) or (left_sum >= m)
            right_ok = (right_len == 1) or (right_sum >= m)
            if left_ok and right_ok and can(i, k) and can(k + 1, j):
                res = True
                break
        memo[key] = res
        return res
    return can(0, n - 1)
