        i = 3
        while i * i <= x:
            if x % i == 0:
                primes.add(i)
                while x % i == 0:
                    x //= i
            i += 2
        if x > 1:
            primes.add(x)
        return primes
    for i in range(n):
        if nums[i] == 1:
            continue
        primes = get_primes(nums[i])
        for p in primes:
