def specialPerm(nums):
    n = len(nums)
    MOD = 10**9 + 7
    dp = [[0] * n for _ in range(1 << n)]
    for i in range(n):
        dp[1 << i][i] = 1
    for mask in range(1 << n):
        for last in range(n):
            if dp[mask][last] == 0:
                continue
            for nxt in range(n):
                if mask & (1 << nxt):
                    continue
                if nums[last] % nums[nxt] == 0 or nums[nxt] % nums[last] == 0:
                    new_mask = mask | (1 << nxt)
                    dp[new_mask][nxt] = (dp[new_mask][nxt] + dp[mask][last]) % MOD
    full = (1 << n) - 1
    return sum(dp[full][i] for i in range(n)) % MOD
